-- Tarecgosa (53396), Stormwind spawn 144403: local ambient flight loop.
-- Preserve the existing flight-capable template, spectral aura 99034 and appearance.
-- move_flag 64 opts into a smooth cyclic flying spline at the existing slower gait.
START TRANSACTION;
DELETE FROM `waypoint_data` WHERE `id`=53396001;
SELECT c.`guid`,53396001,a.`mount`,a.`bytes1`,a.`bytes2`,a.`emote`,a.`auras`
FROM `creature` c JOIN `creature_template_addon` a ON a.`entry`=c.`id`
WHERE c.`guid`=144403 AND c.`id`=53396
ON DUPLICATE KEY UPDATE `path_id`=VALUES(`path_id`);
UPDATE `creature` SET `MovementType`=2,`spawndist`=0,`currentwaypoint`=0
WHERE `guid`=144403 AND `id`=53396;
COMMIT;
